import { Link } from 'react-router-dom';
import { api } from '../lib/api';
import { Layout } from '../components/Layout';
import { Button } from '../components/Button';
import { ColorTag } from '../components/ColorPicker';
import { useToast } from '../components/Toast';
import type { Habit } from '../types';

function getTodayISO(): string {
  return new Date().toISOString().split('T')[0];
}

export function DashboardPage() {
  const queryClient = useQueryClient();
  const { showToast } = useToast();

  const { data: dashboard, isLoading, error } = useQuery({
    queryKey: ['dashboard'],
    queryFn: api.getDashboard,
  });

  const completeMutation = useMutation({
    mutationFn: ({ habitId, date }: { habitId: string; date: string }) =>
      api.completeHabit(habitId, date),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      queryClient.invalidateQueries({ queryKey: ['habits'] });
    },
    onError: (err: Error) => {
      showToast(err.message, 'error');
    },
  });

  const uncompleteMutation = useMutation({
    mutationFn: ({ habitId, date }: { habitId: string; date: string }) =>
      api.uncompleteHabit(habitId, date),
    onSuccess: () => {
      queryClient.invalidateQueries({ queryKey: ['dashboard'] });
      queryClient.invalidateQueries({ queryKey: ['habits'] });
    },
    onError: (err: Error) => {
      showToast(err.message, 'error');
    },
  });

  const toggleComplete = (habit: Habit) => {
    const today = getTodayISO();
    if (habit.completed_today) {
      uncompleteMutation.mutate({ habitId: habit.id, date: today });
    } else {
      completeMutation.mutate({ habitId: habit.id, date: today });
    }
  };

  if (isLoading) {
    return (
      <Layout>
        <div className="animate-pulse space-y-6">
          <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
            {[1, 2, 3].map((i) => (
              <div key={i} className="h-24 bg-surface rounded-card border border-border" />
            ))}
          </div>
          <div className="h-64 bg-surface rounded-card border border-border" />
        </div>
      </Layout>
    );
  }

  if (error) {
    return (
      <Layout>
        <div className="bg-surface rounded-card border border-border p-8 text-center">
          <p className="text-danger">Failed to load dashboard</p>
          <p className="text-sm text-muted mt-1">{(error as Error).message}</p>
        </div>
      </Layout>
    );
  }

  if (!dashboard || dashboard.total_habits === 0) {
    return (
      <Layout>
        <div className="bg-surface rounded-card border border-border p-12 text-center">
          <h2 className="text-lg font-medium text-gray-900 mb-2">No habits yet</h2>
          <p className="text-muted mb-6">Start tracking your daily habits to build streaks.</p>
          <Link to="/habits">
            <Button>Add habit</Button>
          </Link>
        </div>
      </Layout>
    );
  }

  return (
    <Layout>
      <div className="space-y-6">
        <h1 className="text-2xl font-semibold text-gray-900">Dashboard</h1>

        <div className="grid grid-cols-1 sm:grid-cols-3 gap-4">
          <div className="bg-surface rounded-card border border-border p-5">
            <p className="text-sm text-muted">Total Habits</p>
            <p className="text-3xl font-mono font-medium text-gray-900 mt-1">
              {dashboard.total_habits}
            </p>
          </div>
          <div className="bg-surface rounded-card border border-border p-5">
            <p className="text-sm text-muted">Total Completions</p>
            <p className="text-3xl font-mono font-medium text-gray-900 mt-1">
              {dashboard.total_completions}
            </p>
          </div>
          <div className="bg-surface rounded-card border border-border p-5">
            <p className="text-sm text-muted">Active Streaks</p>
            <p className="text-3xl font-mono font-medium text-gray-900 mt-1">
              {dashboard.habits_with_active_streak}
            </p>
          </div>
        </div>

        <div className="bg-surface rounded-card border border-border overflow-hidden">
          <div className="px-5 py-4 border-b border-border">
            <h2 className="font-medium text-gray-900">Today's Habits</h2>
          </div>
          <div className="divide-y divide-border">
            {dashboard.habits.map((habit) => (
              <div
                key={habit.id}
                className="px-5 py-4 flex items-center justify-between hover:bg-gray-50 transition-colors"
              >
                <div className="flex items-center gap-3 min-w-0">
                  <ColorTag color={habit.color} />
                  <Link
                    to={`/habits/${habit.id}`}
                    className="font-medium text-gray-900 hover:text-primary truncate"
                  >
                    {habit.name}
                  </Link>
                </div>
                <div className="flex items-center gap-6">
                  <div className="hidden sm:flex items-center gap-4 text-sm">
                    <span className="text-muted">
                      Current: <span className="font-mono text-gray-900">{habit.current_streak}</span>
                    </span>
                    <span className="text-muted">
                      Best: <span className="font-mono text-gray-900">{habit.longest_streak}</span>
                    </span>
                  </div>
                  <button
                    onClick={() => toggleComplete(habit)}
                    disabled={completeMutation.isPending || uncompleteMutation.isPending}
                    className={`
                      w-10 h-10 rounded-lg border-2 flex items-center justify-center
                      transition-all duration-150 focus:outline-none focus:ring-2 focus:ring-offset-2 focus:ring-primary
                      ${habit.completed_today
                        ? 'bg-success border-success text-white'
                        : 'border-border hover:border-gray-400'
                      }
                    `}
                    aria-label={habit.completed_today ? 'Mark incomplete' : 'Mark complete'}
                  >
                    {habit.completed_today && (
                      <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                        <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M5 13l4 4L19 7" />
                      </svg>
                    )}
                  </button>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </Layout>
  );
}
